"""Authentication helpers."""

import hashlib


def validate_token(token):
    return bool(token) and _check_signature(token)


def parse_token(raw):
    return raw.strip()


def _check_signature(token):
    return hashlib.sha256(token.encode()).hexdigest()


class SessionStore:
    def refresh_session(self, sid):
        return sid

